function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function children(node) {
  if (node instanceof Table) return sortedKeys(node).map((k) => [k, node.map.get(k)])
  return null
}

function ser(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  let items = null
  let open = '['
  let close = ']'
  if (node instanceof Table) {
    open = '{'
    close = '}'
    items = sortedKeys(node).map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.map.get(k), indent + 1)}`)
  } else if (node instanceof AotArray || Array.isArray(node)) {
    const list = node instanceof AotArray ? node.items : node
    items = list.map((v) => pad + ser(v, indent + 1))
  } else {
    return JSON.stringify(node.value)
  }
  if (items.length === 0) return open + close
  return `${open}\n${items.join(',\n')}\n${end}${close}`
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

function typeOf(node) {
  if (node instanceof Table) return 'table'
  if (node instanceof AotArray || Array.isArray(node)) return 'array'
  return node.type
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node instanceof Table) {
      for (const [k, v] of children(node)) visit(v, path === null ? k : `${path}.${k}`)
    } else {
      const list = node instanceof AotArray ? node.items : node
      list.forEach((v, i) => visit(v, `${path}[${i}]`))
    }
  }
  const visit = (node, path) => {
    lines.push(`${path} ${typeOf(node)}`)
    if (node instanceof Table || node instanceof AotArray || Array.isArray(node)) walk(node, path)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

